def transform(grid):
    h, w = len(grid), len(grid[0])
    sep_col = next((j for j in range(w) if len({grid[i][j] for i in range(h)}) == 1 and grid[0][j] != 0), None)
    if sep_col is not None:
        left = [row[:sep_col] for row in grid]
        right = [row[sep_col + 1:] for row in grid]
    else:
        sep_row = next(i for i, row in enumerate(grid) if len(set(row)) == 1 and row[0] != 0)
        left, right = grid[:sep_row], grid[sep_row + 1:]
    return [[2 if a != 0 and b != 0 else 0 for a, b in zip(ra, rb)] for ra, rb in zip(left, right)]
